public static void main(String[] args) throws Exception {
    try (Scanner sc = new Scanner(System.in)) {
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            StringBuffer outLine = new StringBuffer();
            for (int j = 1; j <= n; j++) {
                if (sc.nextInt() == 1) {
                    outLine.append(j).append(" ");
                }
            }
            if (outLine.length() > 0) {
                outLine.setLength(outLine.length() - 1); // Trim the trailing space
            }
            System.out.println(outLine);
        }
    }
}
